label_EnableCluster:
s_mov_b32 s68, ttmp6                               // Read TTMP6 register
s_mov_b32 s69, ttmp7                               // Read TTMP7 register,                                                                        cluster_z | cluster_y.
s_bfe_u32 s70, s68, 262148                         // Etract wg_y.
s_bfe_u32 s71, s68, 262160                         // Etract nwg_y. Value is nwg_y - 1
