s_mul_i32 s[sgprWorkGroup1], s72, s71              // cluster_y * nwg_y
s_add_u32 s[sgprWorkGroup1], s[sgprWorkGroup1], s70 // WorkGroup1 = (cluster_y * nwg_y) + wg_y
s_bfe_u32 s[sgprWorkGroup2], s69, 1048592          // Etract cluster_z.
