s_mul_i32 s[sgprWorkGroup0], ttmp9, s71            // cluster_x * nwg_x
s_add_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s69 // WorkGroup0 = (cluster_x * nwg_x) + wg_x
s_bfe_u32 s72, s68, 262152                         // Etract wg_z.
s_bfe_u32 s68, s68, 262164                         // Etract nwg_z. Value is nwg_z - 1
s_add_u32 s68, s68, 1
s_mul_i32 s[sgprWorkGroup2], s[sgprWorkGroup2], s68 // cluster_z * nwg_z
s_add_u32 s[sgprWorkGroup2], s[sgprWorkGroup2], s72 // WorkGroup2 = (cluster_z * nwg_z) + wg_z
label_RemapWorkGroupDone:
/* Calculate multicast mask */
/* reduce multicast mask to real WGs in cluster */
s_lshr_b32 s16, s[sgprSizeI], 7                    // s16 = s[sgprSizeI] / 128
s_and_b32 s74, 127, s[sgprSizeI]                   // s74 = s[sgprSizeI] % 128
s_addc_u32 s16, s16, 0
s_sub_u32 s68, s[sgprWorkGroup0], s69              // clusterBaseX
s_sub_u32 s16, s16, s68                            // tilesM - clusterBaseX
s_min_u32 s16, s16, 4                              // validX = min(.., cx)
s_bfm_b32 s72, s16, 0                              // maskRow bits = (1<<validX)-1
s_lshr_b32 s16, s[sgprSizeJ], 7                    // s16 = s[sgprSizeJ] / 128
s_and_b32 s74, 127, s[sgprSizeJ]                   // s74 = s[sgprSizeJ] % 128
s_addc_u32 s16, s16, 0
s_and_b32 s17, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s16, s16, s17                            // tilesN * GSU (raw y extent)
s_sub_u32 s68, s[sgprWorkGroup1], s70              // clusterBaseY
s_sub_u32 s16, s16, s68                            // tilesN*GSU - clusterBaseY
s_min_u32 s16, s16, 4                              // validY = min(.., cy)
s_mul_i32 s16, s16, 4                              // validY*cx
s_bfm_b32 s68, s16, 0                              // maskCol bits = (1<<(validY*cx))-1
