s_cbranch_scc1 label_setMulticastMask_OddWave      // Jump if wId is odd
label_setMulticastMask_EvenWave:
s_mov_b32 s[sgprMulticastMask], 0x1111             // Setting maskA for even wave
s_and_b32 s[sgprMulticastMask], s[sgprMulticastMask], s68 // reduce to real WGs
s_lshl_b32 s[sgprMulticastMask], s[sgprMulticastMask], s69 // Setting maskA for even wave
s_and_b32 s[sgprMulticastMask], s[sgprMulticastMask], 0xffff // keep workgroup_mask bits 15:0
s_branch label_setMulticastMaskEnd
label_setMulticastMask_OddWave:
s_mul_i32 s70, s70, s71                            // Shift factor: wg_y * nwg_x
s_mov_b32 s[sgprMulticastMask], 0xf                // Setting maskB for odd wave
s_and_b32 s[sgprMulticastMask], s[sgprMulticastMask], s72 // reduce to real WGs
s_lshl_b32 s[sgprMulticastMask], s[sgprMulticastMask], s70 // Setting maskB for odd wave
s_and_b32 s[sgprMulticastMask], s[sgprMulticastMask], 0xffff // keep workgroup_mask bits 15:0
label_setMulticastMaskEnd:

/* remap workgroup to XCCs */
s_branch label_skip_WGMXCC
s_lshr_b32 s72, s[sgprWGM], 0x10                   // Get WGMXCC
s_ff1_i32_b32 s72, s72                             // Get log(WGMXCC)
s_lshr_b32 s73, s[sgprWGM], 0x16                   // Get CU_Count
/* remap WGs if WGMXCC > 1 ( log(WGMXCC) > 0 ) */
s_cmp_gt_i32 s72, 0
s_cbranch_scc0 label_skip_WGMXCC
/* only remap WGs in the range */
s_lshr_b32 s69, s66, s72
s_lshl_b32 s69, s69, s72
s_cmp_ge_u32 s[sgprWorkGroup0], s69
s_cbranch_scc1 label_skip_WGMXCC
s_cmp_eq_u32 s73, 0                                // CU_Count == 0 ?
s_cbranch_scc0 label_XCCG_nonzero
