s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v3, 5, v[vgprSerial-256]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(32)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v3, 1, v3                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshl_add_u32 v1, v3, 7, v1                       // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(128); 7. final local read offset: flrOffset = lrOffset + WOffset
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v3, 4, v[vgprSerial-256]             // 8. (TileSpan wave-split) hiSel = tid / MI_dim(16)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v3, 1, v3                                // 8. (TileSpan wave-split) hi = (tid / MI_dim) & 1  (lower/upper half-wave)
v_lshl_add_u32 v1, v3, 8, v1                       // 8. (TileSpan wave-split) wave offset in M dimen: wOffset += hi * hiOffset(256); upper half-wave grabs partner block
/* lr1J */
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_and_b32 v3, 31, v[vgprSerial-256]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v2, 15, v3                               // 1. N offset: nIdx = wtid % MI_N(16)
v_lshlrev_b32 v2, 10, v2                           // 1. N offset: nOffset = nIdx * nStride(1024)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v2, 1, v2                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(2)
v_lshrrev_b32 v3, 4, v3                            // 5. K offset: kIdx = wtid / (MIN(16) * MIBB(1))
v_lshl_add_u32 v2, v3, 5, v2                       // 5. K offset: lrKOffset = kIdx * mStride(32); 6. offset in wave: lrOffset = bnOffset + lrKOffset
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v6, 6, v[vgprSerial-256]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(64)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v6, 1, v6                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshl_add_u32 v2, v6, 15, v2                      // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(32768); 7. final local read offset: flrOffset = lrOffset + WOffset
/* lr1J */
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_and_b32 v3, 31, v[vgprSerial-256]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v3, 15, v3                               // 1. N offset: nIdx = wtid % MI_N(16)
v_lshlrev_b32 v3, 2, v3                            // 1. N offset: nOffset = nIdx * nStride(4)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v3, 1, v3                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(2)
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v5, 6, v[vgprSerial-256]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(64)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v5, 1, v5                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshl_add_u32 v3, v5, 7, v3                       // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(128); 7. final local read offset: flrOffset = lrOffset + WOffset
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v5, 4, v[vgprSerial-256]             // 8. (TileSpan wave-split) hiSel = tid / MI_dim(16)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v5, 1, v5                                // 8. (TileSpan wave-split) hi = (tid / MI_dim) & 1  (lower/upper half-wave)
v_lshl_add_u32 v3, v5, 8, v3                       // 8. (TileSpan wave-split) wave offset in N dimen: wOffset += hi * hiOffset(256); upper half-wave grabs partner block

/* local read addresses: final offsets a */
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v4, 5, v[vgprSerial-256]             // 4 = Serial / 32
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v4, 2, v4                            // LSU offset: Get LSU wave_id
s_mov_b32 s65, 1024                                // LSU offset: stride = lsuStride(1024) when umlds==True
v_mul_lo_u32 v4, s65, v4                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT0+PAD)
v_add_nc_u32 v[vgprLocalReadAddrA], v4, v0         // Final Offset: offset = (lro0+lsuoffset)*bpeDS
v_lshrrev_b32 v[vgprLocalReadAddrA], 1, v[vgprLocalReadAddrA] //  (multiple bpe)
v_lshrrev_b32 v5, 10, v[vgprLocalReadAddrA]        // Final Offset: padding 16 per block 1024
v_lshl_add_u32 v[vgprLocalReadAddrA], v5, 4, v[vgprLocalReadAddrA] // Final Offset: padding 16 per block 1024

/* local read addresses: final offsets mxsa */
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v0, 5, v[vgprSerial-256]             // 0 = Serial / 32
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
s_mov_b32 s65, 4096                                // LSU offset: stride = lsuStride(32)*(MTMXSA(128) + PADMXSA(0))
v_mul_lo_u32 v0, s65, v0                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT0+PAD)
v_add_nc_u32 v[vgprLocalReadAddrMXSA], v0, v1      // Final Offset: offset = (lro0+lsuoffset)*bpeDS
                                                   //  (bpe is 1, do nothing)

/* local read addresses: final offsets mxsb */
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v0, 5, v[vgprSerial-256]             // 0 = Serial / 32
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
                                                   // LSU offset: stride = lsuStride(32)*(MTMXSB(128) + PADMXSB(0)) (dup assign opt.)
v_mul_lo_u32 v0, s65, v0                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT1+PAD)
v_add_nc_u32 v[vgprLocalReadAddrMXSB], v0, v3      // Final Offset: offset = (lro1+lsuoffset)*bpeDS
                                                   //  (bpe is 1, do nothing)

/* local read addresses: final offsets b */
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v0, 5, v[vgprSerial-256]             // 0 = Serial / 32
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
s_mov_b32 s65, 1024                                // LSU offset: stride = lsuStride(1024) when umlds==True
v_mul_lo_u32 v0, s65, v0                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT1+PAD)
v_add_nc_u32 v[vgprLocalReadAddrB], v0, v2         // Final Offset: offset = (lro1+lsuoffset)*bpeDS
v_lshrrev_b32 v[vgprLocalReadAddrB], 1, v[vgprLocalReadAddrB] //  (multiple bpe)
v_lshrrev_b32 v1, 10, v[vgprLocalReadAddrB]        // Final Offset: padding 16 per block 1024
v_lshl_add_u32 v[vgprLocalReadAddrB], v1, 4, v[vgprLocalReadAddrB] // Final Offset: padding 16 per block 1024

/* local read addresses: declare addresses a */
v_add_nc_u32 v[vgprLocalReadAddrA+1], 65536, v[vgprLocalReadAddrA] // Final Offset Plus 64K

/* local read addresses: declare addresses mxsa */
v_add_co_u32 v[vgprLocalReadAddrMXSA+0], vcc_lo, 0x10400, v[vgprLocalReadAddrMXSA+0] //  += LdsOffsetMXSA (lower)

/* local read addresses: declare addresses mxsb */
v_add_co_u32 v[vgprLocalReadAddrMXSB+0], vcc_lo, 0x11400, v[vgprLocalReadAddrMXSB+0] //  += LdsOffsetMXSB (lower)

/* local read addresses: declare addresses b */
v_add_co_u32 v[vgprLocalReadAddrB+0], vcc_lo, 0x12400, v[vgprLocalReadAddrB+0] //  += LdsOffsetB (lower)
v_add_nc_u32 v[vgprLocalReadAddrB+1], 65536, v[vgprLocalReadAddrB] // Final Offset Plus 64K
s_set_vgpr_msb 64                                  // src0: 0, src1: 0, src2: 0, dst: 1
v_add_nc_u32 v[vgprLocalReadSwapAddrA-256], 141312, v[vgprLocalReadAddrA] // Calculate starting lds addr of second buffer
s_set_vgpr_msb 16449                               // src0: 1, src1: 0, src2: 0, dst: 1
v_xor_b32 v[vgprLocalReadSwapAddrA-256], v[vgprLocalReadSwapAddrA-256], v[vgprLocalReadAddrA] // xor both lds buffer offsets to enable swapping
s_set_vgpr_msb 16704                               // src0: 0, src1: 0, src2: 0, dst: 1
v_add_nc_u32 v[vgprLocalReadSwapAddrMXSA-256], 141312, v[vgprLocalReadAddrMXSA] // Calculate starting lds addr of second buffer
s_set_vgpr_msb 16449                               // src0: 1, src1: 0, src2: 0, dst: 1
v_xor_b32 v[vgprLocalReadSwapAddrMXSA-256], v[vgprLocalReadSwapAddrMXSA-256], v[vgprLocalReadAddrMXSA] // xor both lds buffer offsets to enable swapping
s_set_vgpr_msb 16704                               // src0: 0, src1: 0, src2: 0, dst: 1
v_add_nc_u32 v[vgprLocalReadSwapAddrB-256], 141312, v[vgprLocalReadAddrB] // Calculate starting lds addr of second buffer
s_set_vgpr_msb 16449                               // src0: 1, src1: 0, src2: 0, dst: 1
v_xor_b32 v[vgprLocalReadSwapAddrB-256], v[vgprLocalReadSwapAddrB-256], v[vgprLocalReadAddrB] // xor both lds buffer offsets to enable swapping
s_set_vgpr_msb 16704                               // src0: 0, src1: 0, src2: 0, dst: 1
v_add_nc_u32 v[vgprLocalReadSwapAddrMXSB-256], 141312, v[vgprLocalReadAddrMXSB] // Calculate starting lds addr of second buffer
s_set_vgpr_msb 16449                               // src0: 1, src1: 0, src2: 0, dst: 1
v_xor_b32 v[vgprLocalReadSwapAddrMXSB-256], v[vgprLocalReadSwapAddrMXSB-256], v[vgprLocalReadAddrMXSB] // xor both lds buffer offsets to enable swapping

/******************************************/
/* Local Write Addresses                  */
/******************************************/

/* local write addresses: first offset a */

/* local write addresses: first offset b */
s_lshr_b32 s[sgprNumWorkGroups0], s[sgprSizesFree+0], 7 // s[sgprNumWorkGroups0] = s[sgprSizesFree+0] / 128
s_and_b32 s65, 127, s[sgprSizesFree+0]             // s65 = s[sgprSizesFree+0] % 128
s_cmp_gt_u32 s65, 0                                // Check if remainder > 0
s_addc_u32 s[sgprNumWorkGroups0], s[sgprNumWorkGroups0], 0 // Increment if remainder > 0
s_lshr_b32 s[sgprNumWorkGroups1], s[sgprSizesFree+1], 7 // s[sgprNumWorkGroups1] = s[sgprSizesFree+1] / 128
s_and_b32 s65, 127, s[sgprSizesFree+1]             // s65 = s[sgprSizesFree+1] % 128
s_cmp_gt_u32 s65, 0                                // Check if remainder > 0
s_addc_u32 s[sgprNumWorkGroups1], s[sgprNumWorkGroups1], 0 // Increment if remainder > 0
s_and_b32 s65, s[sgprArgType], 0xff                // mask ArgType domain (bits 8+ are internal flags)
s_cmp_eq_u32 s65, 2                                // ArgType == 2 ?
s_cbranch_scc0 label_SkipWaitForUserArgs_2         // skip wait if ArgType != 2
s_wait_kmcnt 0                                     // wait for 16/0 bytes of kern args
label_SkipWaitForUserArgs_2:  /// skip kern args wait if ArgType != 2

/* Early stop if N(SizeFreeJ) == 0 */
s_cmp_eq_u32 s[sgprSizeJ], 0
s_cbranch_scc0 label_NoEarlyStop_N0
label_EarlyStop_if_N_is_0:
s_endpgm
label_NoEarlyStop_N0:

/* Early stop padded work-groups in a boundary cluster (grid rounded up to ClusterDim) */
s_cmp_ge_u32 s[sgprWorkGroup0], s[sgprNumWorkGroups0] // padded if WorkGroup0 >= tilesM
s_cbranch_scc1 label_ClusterPad_EarlyStop_1
s_and_b32 s18, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s18, s[sgprNumWorkGroups1], s18          // tilesN * GSU
s_cmp_ge_u32 s[sgprWorkGroup1], s18                // padded if WorkGroup1 >= tilesN*GSU
s_cbranch_scc1 label_ClusterPad_EarlyStop_1
s_branch label_ClusterPad_NoEarlyStop_1
label_ClusterPad_EarlyStop_1:
s_endpgm                                           // padded work-group: exit before any load/barrier
label_ClusterPad_NoEarlyStop_1:
s_branch label_MultiGemmEnd                        // Already using 3D WorkGroups, skip remap

/* remap wg from 1D(idxWG012) to 3D(wg2,wg1,wg0) */
/* wg2 = idxWG012 * smallMagicNumber(1/(numWG0*numWG1)) */
s_mul_i32 s18, s[sgprNumWorkGroups0], s[sgprNumWorkGroups1]
s_and_b32 s19, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s18, s18, s19
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_cvt_f32_u32 v0, s18                              // s18 = s[sgprWorkGroup0] / s18
v_rcp_iflag_f32 v0, v0                             // s18 = s[sgprWorkGroup0] / s18
v_mov_b32 v1, 0x4f7ffffe                           // 2^32 - 512
v_mul_f32 v0, v1, v0                               // 2^32 / divisor
v_cvt_u32_f32 v0, v0                               // s18 = s[sgprWorkGroup0] / s18
v_mul_lo_u32 v1, v0, s18                           // refine 2^32 / divisor
v_sub_nc_u32 v1, 0, v1                             // refine 2^32 / divisor
v_mul_hi_u32 v1, v0, v1                            // refine 2^32 / divisor
v_add_nc_u32 v0, v0, v1                            // refine 2^32 / divisor
v_mul_hi_u32 v0, s[sgprWorkGroup0], v0             // s18 = s[sgprWorkGroup0] / s18
v_mul_lo_u32 v1, v0, s18                           // s18 = s[sgprWorkGroup0] / s18
v_sub_nc_u32 v1, s[sgprWorkGroup0], v1             // s18 = s[sgprWorkGroup0] / s18
v_cmp_ge_u32 vcc_lo, v1, s18                       // remainder >= divisor?
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s18                           // remainder - divisor
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_ge_u32 vcc_lo, v1, s18                       // remainder >= divisor?
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s18                           // remainder - divisor
s_mov_b32 exec_lo, -1                              // Reset exec
v_readfirstlane_b32 s18, v0                        // quotient
s_mov_b32 s[sgprWorkGroup2], s18
/* idxWG01 = idxWG012 - wg2 * numWG0 * numWG1 */
s_mul_i32 s18, s[sgprNumWorkGroups1], s[sgprNumWorkGroups0]
s_mul_i32 s18, s18, s[sgprWorkGroup2]
s_mul_i32 s18, s18, s19
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s18
/* wg1 = idxWG01 * smallMagicNumber(1/numWG0) */
v_cvt_f32_u32 v0, s[sgprNumWorkGroups0]            // s18 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_rcp_iflag_f32 v0, v0                             // s18 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_mov_b32 v1, 0x4f7ffffe                           // 2^32 - 512
v_mul_f32 v0, v1, v0                               // 2^32 / divisor
v_cvt_u32_f32 v0, v0                               // s18 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_mul_lo_u32 v1, v0, s[sgprNumWorkGroups0]         // refine 2^32 / divisor
v_sub_nc_u32 v1, 0, v1                             // refine 2^32 / divisor
v_mul_hi_u32 v1, v0, v1                            // refine 2^32 / divisor
v_add_nc_u32 v0, v0, v1                            // refine 2^32 / divisor
v_mul_hi_u32 v0, s[sgprWorkGroup0], v0             // s18 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_mul_lo_u32 v1, v0, s[sgprNumWorkGroups0]         // s18 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_sub_nc_u32 v1, s[sgprWorkGroup0], v1             // s18 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_cmp_ge_u32 vcc_lo, v1, s[sgprNumWorkGroups0]     // remainder >= divisor?
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s[sgprNumWorkGroups0]         // remainder - divisor
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_ge_u32 vcc_lo, v1, s[sgprNumWorkGroups0]     // remainder >= divisor?
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s[sgprNumWorkGroups0]         // remainder - divisor
s_mov_b32 exec_lo, -1                              // Reset exec
v_readfirstlane_b32 s18, v0                        // quotient
s_mov_b32 s[sgprWorkGroup1], s18
/* wg0 = idxWG01 - wg1 * numWG0 */
s_mul_i32 s18, s18, s[sgprNumWorkGroups0]
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s18

/* Early stop if wg exceed */
s_cmp_ge_u32 s[sgprWorkGroup2], s[sgprSizesFree+2]
s_cbranch_scc0 label_NoEarlyStop_wgExceed
label_EarlyStop_if_wg_exceed:
s_endpgm
label_NoEarlyStop_wgExceed:

label_MultiGemmEnd:
.set sgprtdmAGroup0, 20
.set sgprtdmAGroup1, 24
.set sgprtdmMXSAGroup0, 64
.set sgprtdmMXSAGroup1, 68
.set sgprtdmBGroup0, sgprtdmAGroup0+0
.set sgprtdmBGroup1, sgprtdmAGroup1+0
.set sgprtdmMXSBGroup0, sgprtdmMXSAGroup0+0
.set sgprtdmMXSBGroup1, sgprtdmMXSAGroup1+0
.set sgprtdmABIncs, 18
.set sgprtdmMXSAMXSBIncs, 19
.set sgprGlobalReadIncsA, 63
.set sgprGlobalReadIncsMXSA, 76
.set sgprGlobalReadIncsB, 77
.set sgprGlobalReadIncsMXSB, 78
.set sgprGL2PrefetchIncA, 79
.set sgprGL2PrefetchIncB, 80
.set sgprGL2PrefetchIncMXSA, 81
.set sgprGL2PrefetchIncMXSB, 82
s_and_b32 s83, s[sgprArgType], 0xff                // mask ArgType domain (bits 8+ are internal flags)
s_cmp_eq_u32 s83, 3                                // ArgType == 3 for General Batched GEMM
s_cbranch_scc1 label_Skip_Address_Prepad_For_Pointer_Array
label_Skip_Address_Prepad_For_Pointer_Array:  /// Skip pre-padding of address for pointer array case

/* Short circuit condition if Alpha == 0, then sumDims=0 */
v_cmp_eq_f32 vcc_lo, s[sgprAlpha], 0.0             // s[Alpha] == 0.0f ?
s_cbranch_vccz label_AlphaNonZero                  // branch if s[Alpha] != 0
s_mov_b32 s[sgprSizesSum+0], 0                     // Set summation dim=0 if Alpha == 0
label_AlphaNonZero:
s_setreg_IMM32_b32 hwreg(26,2,1), 1                // Disable WMMA arb stall
s_and_b32 s83, s[sgprGSU], 0xfff                   // Restore GSU
s_cmp_eq_u32 s83, 1                                // GSU == 1 ?
s_cbranch_scc1 label_GSU                           // branch if GSU == 1
s_and_b32 s83, s[sgprGSU], 0x4000                  // SCC = (GSUWGMRR == 1) ?
s_cbranch_scc1 label_GSUWGMRR                      // branch if GSUWGMRR == 1
s_and_b32 s83, s[sgprGSU], 0xfff                   // Restore GSU
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_mov_b32 v1, 0x4f7ffffe                           // 2^32 - 512
v_cvt_f32_u32 v0, s83                              // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s83
v_rcp_iflag_f32 v0, v0                             // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s83
v_mul_f32 v0, v1, v0                               // 2^32 / divisor
v_cvt_u32_f32 v0, v0                               // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s83
v_mul_lo_u32 v1, v0, s83                           // refine 2^32 / divisor
v_sub_nc_u32 v1, 0, v1                             // refine 2^32 / divisor
v_mul_hi_u32 v1, v0, v1                            // refine 2^32 / divisor
v_add_nc_u32 v0, v0, v1                            // refine 2^32 / divisor
v_mul_hi_u32 v0, s[sgprWorkGroup1], v0             // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s83
v_mul_lo_u32 v1, v0, s83                           // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s83
v_sub_nc_u32 v1, s[sgprWorkGroup1], v1             // s[sgprGSUSumIdx] = s[sgprWorkGroup1] % s83
v_cmp_ge_u32 vcc_lo, v1, s83                       // remainder >= divisor?
s_wait_alu depctr_va_vdst(0)
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s83                           // remainder - divisor
s_wait_alu depctr_va_vdst(0)
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_ge_u32 vcc_lo, v1, s83                       // remainder >= divisor?
s_wait_alu depctr_va_vdst(0)
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s83                           // remainder - divisor
s_wait_alu depctr_va_vdst(0)
s_mov_b32 exec_lo, -1                              // Reset exec
v_readfirstlane_b32 s[sgprWorkGroup1], v0          // quotient
v_readfirstlane_b32 s[sgprGSUSumIdx], v1           // remainder
s_branch label_GSUWGMRR_End
